s=s[:a]+fn+s[b:]
# Lock-aware editing + Send to Scan.
a=s.index(' async function openEditDaily');b=s.index(' async function doScan',a)
fn=''' async function openEditDaily(d:Daily){if(d.submitted_to_scan)return msg("","This daily plan is locked because it has been submitted to Scan Station.");setEditD(d);setStart(d.shift_start.slice(0,5));setEnd(d.shift_end.slice(0,5));setBreakMinutes(String(d.break_minutes||0));setPlanQuantity(String(d.planned_quantity));setRate(String(d.target_per_hour));let r=await supabase!.from("daily_plan_hour_targets").select("id,hour_number,hour_start,hour_end,planned_quantity").eq("daily_plan_id",d.id).order("hour_number");setHours(r.data||[]);let m=await supabase!.from("daily_plan_manpower").select("manpower_count,actual_count").eq("daily_plan_id",d.id).maybeSingle();setManpower(String(m.data?.manpower_count||0));setActualManpower(String(m.data?.actual_count||0));setModal("editDaily")}\n async function saveEditDaily(){if(!supabase||!editD)return;let hourly=hours.reduce((n,h)=>n+(+h.planned_quantity||0),0),cap=Math.floor(Math.max(0,dur(start,end)-((+breakMinutes||0)/60))*(+rate||0));if(hourly>cap)return msg(`Hourly target ${hourly} exceeds capacity ${cap}`);let r=await supabase.from("daily_production_plans").update({shift_start:`${start}:00`,shift_end:`${end}:00`,break_minutes:+breakMinutes||0,target_per_hour:+rate,planned_hours:Math.max(0,dur(start,end)-((+breakMinutes||0)/60)),max_capacity_quantity:cap}).eq("id",editD.id);if(r.error)return msg(r.error.message);await saveHours(editD.id);await supabase.from("daily_plan_manpower").upsert({daily_plan_id:editD.id,manpower_category:"production",manpower_count:+manpower||0,actual_count:+actualManpower||0},{onConflict:"daily_plan_id,manpower_category"});setModal(null);await loadDaily();msg("","Daily shift plan updated.")}\n async function sendToScan(d:Daily){if(!supabase||d.submitted_to_scan)return;let r=await supabase.from("daily_production_plans").update({submitted_to_scan:true,locked_at:new Date().toISOString(),locked_by:session?.user.id,status:"running"}).eq("id",d.id).eq("submitted_to_scan",false);if(r.error)return msg(r.error.message);setScanPlan(d.id);setPage("Scan Events");await loadDaily();msg("","Daily plan submitted to Scan Station and locked for editing.")}\n'''
s=s[:a]+fn+s[b:]
s=s.replace('setLast(row);setScans(x=>[row,...x.filter(y=>y.id!==row.id)].slice(0,2000));', 'setLast(row);setScans(x=>[row,...x.filter(y=>y.id!==row.id)].slice(0,2000));if(row.daily_plan_id)await supabase.from("daily_production_plans").update({submitted_to_scan:true,locked_at:new Date().toISOString(),locked_by:session?.user.id,status:"running"}).eq("id",row.daily_plan_id).eq("submitted_to_scan",false);')
s=s.replace('<td><button className="icon-button" onClick={()=>openEditDaily(d)}>Edit</button></td>', '<td>{d.submitted_to_scan?<span className="locked-action">🔒 Locked</span>:<div className="daily-actions"><button className="button button-sm button-secondary" onClick={()=>openEditDaily(d)}>Edit plan</button><button className="button button-sm button-primary" onClick={()=>sendToScan(d)}>Send to scan</button></div>}</td>')
needle='<Field l="Target / hour"><input type="number" value={rate} onChange={e=>{setRate(e.target.value);setHours(makeHours(start,end,+e.target.value))}}/></Field><Field l="Manpower">'
replacement='<Field l="Break / non-productive minutes"><input type="number" min="0" value={breakMinutes} onChange={e=>setBreakMinutes(e.target.value)}/></Field><Field l="Target / hour"><input type="number" value={rate} onChange={e=>{setRate(e.target.value);setHours(makeHours(start,end,+e.target.value))}}/></Field><Field l="Planned quantity"><input type="number" min="1" value={planQuantity} onChange={e=>setPlanQuantity(e.target.value)}/></Field><Field l="Manpower planned"><input type="number" min="0" value={manpower} onChange={e=>setManpower(e.target.value)}/></Field><Field l="Manpower actually used"><input type="number" min="0" value={actualManpower} onChange={e=>setActualManpower(e.target.value)}/></Field><Field l="Manpower">'
s=s.replace(needle,replacement)
s=s.replace('<div><span>PLANNED QUANTITY</span><strong>{hours.reduce((n,h)=>n+h.planned_quantity,0)}</strong></div><div><span>SHIFT HOURS</span><strong>{dur(start,end).toFixed(1)}</strong></div><div><span>MAX CAPACITY</span><strong>{Math.floor(dur(start,end))*(+rate||0)}</strong></div>', '<div><span>PLANNED QUANTITY</span><strong>{Number(planQuantity||0).toLocaleString()}</strong></div><div><span>PRODUCTIVE HOURS</span><strong>{Math.max(0,dur(start,end)-((+breakMinutes||0)/60)).toFixed(1)}</strong></div><div><span>MAX CAPACITY</span><strong>{Math.floor(Math.max(0,dur(start,end)-((+breakMinutes||0)/60))*(+rate||0))}</strong></div>')
p.write_text(s)
